word_list = []
while True:
    word = input("Input word: ")
    if word == "end":
        break
    word_list.append(word)

while True:
    search = input("Input search: ")
    if search == "end":
        break

    status = "not found"
    for i in range(len(word_list)):
        if search == word_list[i]:
            status = "match"
            break
        elif search in word_list[i]:
            status = "similar to " + word_list[i]
            break
    print(status)

